info.description:
FIRST ONE I MADE!!@-moz-document url-prefix("https://archiveofourown.org/skins/new") {
@font-face {
    font-family: 'RiordanGreek';
    src: url('https://cdn.jsdelivr.net/gh/user/repo@main/greekfont.woff2');
}

body {
    font-family: 'RiordanGreek', serif;
}
body {
    background: url('https://example.com/parchment.jpg') repeat;
}
a,
.heading {
    color: #ff8f00;
}
.chapter {
    border-top: 4px double #4b0082;
    padding-top: 1em;
}
}

